import { useState, useEffect } from "react";
import deMol from "../logos/demol.jpg";
import clockSound from "../sound/clock.mp3";

export default function GamePage() {
  const targetDate = new Date("2025-03-30T09:30:00").getTime();
  const [timeLeft, setTimeLeft] = useState(calculateTimeLeft());
  const [audioStarted, setAudioStarted] = useState(false);
  const [password, setPassword] = useState("");
  const [passwordMessage, setPasswordMessage] = useState(null); // Store the message for each password
  const [newText, setNewText] = useState(""); // Store the new text for each password
  const [messageVisible, setMessageVisible] = useState(false); // To show the welcome message briefly
  const audio = new Audio(clockSound);

  const passwords = [
    { password: "game123", message: "Welcome to the game, Player 1!", newText: "Welkom, Mol" },
    { password: "code456", message: "You found the secret, Player 2!", newText: "You’ve unlocked the second level!" },
    { password: "hidden789", message: "Welcome to the game, Player!", newText: "You’ve unlocked the third level!" },
    { password: "power101", message: "Welcome to the game, Player!", newText: "You’ve unlocked the fourth level!" },
    { password: "mystery202", message: "Welcome to the game, Player!", newText: "You’ve unlocked the fifth level!" },
    { password: "quest303", message: "Welcome to the game, Player!", newText: "You’ve unlocked the sixth level!" },
    { password: "unlock404", message: "Welcome to the game, Player!", newText: "You’ve unlocked the seventh level!" },
    { password: "master505", message: "Welcome to the game, Player!", newText: "You’ve unlocked the eighth level!" },
    { password: "hero606", message: "Welcome to the game, Player!", newText: "You’ve unlocked the ninth level!" },
    { password: "legend707", message: "Welcome to the game, Player!", newText: "You’ve unlocked the tenth level!" },
  ];

  function calculateTimeLeft() {
    const now = new Date().getTime();
    const difference = targetDate - now;
    return {
      days: Math.floor(difference / (1000 * 60 * 60 * 24)),
      hours: Math.floor((difference / (1000 * 60 * 60)) % 24),
      minutes: Math.floor((difference / (1000 * 60)) % 60),
      seconds: Math.floor((difference / 1000) % 60),
    };
  }

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeLeft(calculateTimeLeft());
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  const startAudio = () => {
    if (!audioStarted) {
      audio.loop = true;
      audio.volume = 0.5;
      audio.play().catch((err) => console.error("Audio playback error:", err));
      setAudioStarted(true);
    }
  };

  const handlePasswordChange = (e) => {
    setPassword(e.target.value);
  };

  const handlePasswordSubmit = () => {
    const foundPassword = passwords.find((entry) => entry.password === password);
    if (foundPassword) {
      setPasswordMessage(foundPassword.message);
      setNewText(foundPassword.newText);
      setMessageVisible(true);
      setTimeout(() => setMessageVisible(false), 2000); // Hide message after 2 seconds
    } else {
      setPasswordMessage("Wrong Password, Try Again!");
    }
  };

  return (
    <div
      onClick={startAudio} // 👈 User must click the page to start sound
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        minHeight: "100vh",
        backgroundColor: "black",
        color: "white",
        padding: "20px",
        textAlign: "center",
        fontFamily: "'Anton', sans-serif", // Heavy font for impact
      }}
    >
      <img
        src={deMol}
        alt="Game Image"
        style={{ width: "256px", height: "auto", marginBottom: "24px" }}
      />

      <div
        style={{
          fontSize: "48px", // Bigger text
          fontWeight: "bold",
          textTransform: "uppercase", // ALL CAPS
          letterSpacing: "4px", // Spaced-out for ominous effect
          marginBottom: "16px",
        }}
      >
        {timeLeft.days}D {timeLeft.hours}H {timeLeft.minutes}M {timeLeft.seconds}S
      </div>

      <input
        type="password"
        value={password}
        onChange={handlePasswordChange}
        placeholder="Enter Password"
        style={{
          padding: "10px",
          fontSize: "16px",
          borderRadius: "5px",
          border: "1px solid #ccc",
          textAlign: "center",
        }}
      />
      <button
        onClick={handlePasswordSubmit}
        style={{
          padding: "10px 20px",
          marginTop: "10px",
          fontSize: "16px",
          cursor: "pointer",
          borderRadius: "5px",
          backgroundColor: "#444",
          color: "white",
        }}
      >
        Submit
      </button>

      {passwordMessage && (
        <div
          style={{
            marginTop: "20px",
            color: passwordMessage.includes("Wrong") ? "red" : "green",
            fontWeight: "bold",
            fontSize: "18px",
          }}
        >
          {passwordMessage}
        </div>
      )}

      {messageVisible && passwordMessage !== "Wrong Password, Try Again!" && (
        <div
          style={{
            marginTop: "20px",
            fontSize: "24px",
            color: "yellow",
            fontWeight: "bold",
          }}
        >
          {passwordMessage}
        </div>
      )}

      {passwordMessage && !passwordMessage.includes("Wrong") && (
        <div
          style={{
            marginTop: "20px",
            fontSize: "20px",
            color: "white",
            fontWeight: "bold",
          }}
        >
          {newText}
        </div>
      )}
    </div>
  );
}
