import React from 'react';
import { Link } from 'react-router-dom';
import { Helmet } from 'react-helmet';
function getCurrentSchoolYear() {
  const today = new Date();
  const year = today.getFullYear();
  const month = today.getMonth();

  // School year changes on the first of July
  if (month >= 6) {
    // Months are 0-indexed in JavaScript, so 6 corresponds to July
    return `${year}-${year + 1}`;
  } else {
    return `${year - 1}-${year}`;
  }
}

function isLinkActive() {
  const now = new Date();
  const targetDate = new Date(now.getFullYear(), 8, 2, 12); // August 14th, 10 PM

  // Check if the current date and time is after the target date
  return now >= targetDate;
}

